#include <cstdint>
#include <optional>
#include <string>
#include <vector>

constexpr std::uint32_t kMaxPayload{ 4096 };

struct Message { std::uint16_t version; std::uint16_t flags; std::string payload; };

std::vector<std::uint8_t> encode(std::uint16_t flags, const std::string& payload)
{
    std::vector<std::uint8_t> out;
    auto put = [&](std::uint32_t v, int n) { for (int i{ 0 }; i < n; ++i) out.push_back(static_cast<std::uint8_t>(v >> (8 * i))); };
    put(1, 2);
    put(flags, 2);
    put(static_cast<std::uint32_t>(payload.size()), 4);
    out.insert(out.end(), payload.begin(), payload.end());
    return out;
}

std::optional<Message> decode(const std::vector<std::uint8_t>& bytes)
{
    if (bytes.size() < 8) return std::nullopt;
    auto get = [&](std::size_t at, int n) { std::uint32_t v{ 0 }; for (int i{ n - 1 }; i >= 0; --i) v = (v << 8) | bytes[at + static_cast<std::size_t>(i)]; return v; };
    const auto version{ static_cast<std::uint16_t>(get(0, 2)) };
    const auto flags{ static_cast<std::uint16_t>(get(2, 2)) };
    const std::uint32_t length{ get(4, 4) };
    if (version != 1) return std::nullopt;
    if (length > kMaxPayload || length != bytes.size() - 8) return std::nullopt;   // too big, cut short, or extra bytes
    return Message{ version, flags, std::string(bytes.begin() + 8, bytes.end()) };
}

unitTests:
TEST("the exact bytes") { CHECK(encode(0x0002, "hi") == std::vector<std::uint8_t>({ 1, 0, 2, 0, 2, 0, 0, 0, 'h', 'i' })); }
TEST("round trip") { const auto m{ decode(encode(7, "hello, kernel")) }; CHECK(m.has_value()); CHECK_EQ(m->flags, std::uint16_t{ 7 }); CHECK_EQ(m->payload, std::string("hello, kernel")); }
TEST("an empty payload") { const auto m{ decode(encode(0, "")) }; CHECK(m.has_value()); CHECK(m->payload.empty()); }
TEST("too short for a header") { CHECK(!decode({ 1, 0, 0 }).has_value()); }
TEST("wrong version") { auto b{ encode(0, "x") }; b[0] = 2; CHECK(!decode(b).has_value()); }
TEST("length larger than the data") { auto b{ encode(0, "abc") }; b[4] = 10; CHECK(!decode(b).has_value()); }
TEST("extra bytes") { auto b{ encode(0, "abc") }; b.push_back('!'); CHECK(!decode(b).has_value()); }
TEST("payload over the limit") { CHECK(!decode(encode(0, std::string(5000, 'x'))).has_value()); CHECK(decode(encode(0, std::string(4096, 'x'))).has_value()); }
TEST("a huge length field does not overflow") { std::vector<std::uint8_t> b{ 1, 0, 0, 0, 0xFF, 0xFF, 0xFF, 0xFF }; CHECK(!decode(b).has_value()); }

